#include "NativeProtocol.h"
#include "ShortcutModel.h"
#include "WindowsCommandLine.h"
#include <cassert>
#include <iostream>
int main(){assert(WindowsCommandLine::quote(L"")==L"\"\"");assert(WindowsCommandLine::quote(L"C:\\Folder Space\\python.exe")==L"\"C:\\Folder Space\\python.exe\"");assert(WindowsCommandLine::quote(L"C:\\path\\")==L"\"C:\\path\\\\\"");assert(WindowsCommandLine::quote(L"a\"b")==L"\"a\\\"b\"");std::wstring units;units+=wchar_t(0xD83D);units+=wchar_t(0xDE00);assert(WindowsCommandLine::quote(units)==L"\""+units+L"\"");std::string id="12345678-1234-1234-1234-123456789abc";using J=nlohmann::json;J j={{"id",id},{"operation","capture.start"},{"args",J::object()},{"expiresAt",1100.0}};assert(NativeProtocol::validate(j,id,1000).empty());
 J cancelArgs={{"requestId",id}};assert(NativeProtocol::captureCancelArguments(cancelArgs));assert(NativeProtocol::captureCancelMatches(cancelArgs,id));assert(!NativeProtocol::captureCancelMatches(cancelArgs,""));assert(!NativeProtocol::captureCancelMatches(cancelArgs,"12345678-1234-1234-1234-123456789abd"));
 for(J invalid:{J::object(),J::array(),J{{"requestId",123}},J{{"requestId","../capture"}},J{{"requestId","12345678-1234-1234-1234-123456789ABC"}},J{{"requestId",id},{"all",true}}})assert(!NativeProtocol::captureCancelArguments(invalid));
 j["operation"]="capture.cancel";j["args"]=cancelArgs;assert(NativeProtocol::validate(j,id,1000).empty());j["operation"]="capture.start";j["args"]=J::object();assert(NativeProtocol::validate(j,"../"+id,1000)=="invalidRequest");j["operation"]="shell.run";assert(NativeProtocol::validate(j,id,1000)=="unsupported");j["operation"]="pair.approve";j["expiresAt"]=999;assert(NativeProtocol::validate(j,id,1000)=="expired");j["expiresAt"]=6000;assert(NativeProtocol::validate(j,id,1000)=="invalidRequest");j["expiresAt"]=1100;j["args"]=J::array();assert(NativeProtocol::validate(j,id,1000)=="invalidRequest");ShortcutModel::Key k;assert(ShortcutModel::parse("Control+Shift+F9",k)&&k.mods==6&&k.key==0x78);assert(ShortcutModel::normalized(k)=="Control+Shift+F9");assert(!ShortcutModel::parse("Control+C",k));assert(!ShortcutModel::parse("Control+Shift+F10",k));assert(!ShortcutModel::parse("Control+Control+F8",k));assert(!ShortcutModel::parse("Alt+F999999999999999",k));assert(ShortcutModel::parse("",k)&&!k.enabled);ShortcutModel::Key a,b;assert(ShortcutModel::parse("Control+Shift+A",a)&&ShortcutModel::parse("Shift+Ctrl+A",b));assert(!ShortcutModel::validSet({a,b}));std::cout<<"PASS: UUID/expiry/allowlist/native JSON shape; scoped cancellation validates canonical UUID and excludes stale/other capture IDs; shortcut modifiers, reserved stop key, disabled keys, duplicates and numeric bounds; empty/spaced/quoted/trailing-backslash/surrogate argv\n";}
